public class NewSpellHandler
{
	public Dictionary<ElementType, int> elementUnlockCount = new Dictionary<ElementType, int>
	{
		{
			ElementType.Chaos,
			0
		},
		{
			ElementType.Earth,
			0
		},
		{
			ElementType.Fire,
			0
		},
		{
			ElementType.Air,
			0
		},
		{
			ElementType.Water,
			0
		},
		{
			ElementType.Lightning,
			0
		}
	};

	public Dictionary<SpellBookUI.SkillEquipType, int> skillTypeUnlockCount = new Dictionary<SpellBookUI.SkillEquipType, int>
	{
		{
			SpellBookUI.SkillEquipType.Basic,
			0
		},
		{
			SpellBookUI.SkillEquipType.Dash,
			0
		},
		{
			SpellBookUI.SkillEquipType.Optional,
			0
		},
		{
			SpellBookUI.SkillEquipType.Signature,
			0
		}
	};

	public Dictionary<string, NewSpellRecord> newSpells = new Dictionary<string, NewSpellRecord>();

	public bool HasRecord(string skillID)
	{
		if (!newSpells.ContainsKey(skillID))
		{
			return false;
		}
		return true;
	}

	public NewSpellRecord GetRecord(string skillID)
	{
		if (!newSpells.ContainsKey(skillID))
		{
			return null;
		}
		return newSpells[skillID];
	}

	public bool HasRecord(string skillID, SpellBookUI.SkillEquipType skillType)
	{
		if (!newSpells.ContainsKey(skillID))
		{
			return false;
		}
		return newSpells[skillID].IsSkillType(skillType);
	}

	public int GetUnlockCount(ElementType element)
	{
		return elementUnlockCount[element];
	}

	public int GetUnlockCount(SpellBookUI.SkillEquipType skillType)
	{
		return skillTypeUnlockCount[skillType];
	}

	public int GetUnlockCount(SpellBookUI.SkillEquipType skillType, ElementType element)
	{
		if (skillTypeUnlockCount[skillType] == 0)
		{
			return 0;
		}
		if (elementUnlockCount[element] == 0)
		{
			return 0;
		}
		int num = 0;
		foreach (NewSpellRecord value in newSpells.Values)
		{
			if (value.element == element && value.IsSkillType(skillType))
			{
				num++;
			}
		}
		return num;
	}

	public void Add(string skillID, ElementType element, bool baseUnlocked, bool sigUnlocked, SpellBookUI.SkillEquipType skillEquipType, Player player)
	{
		Player.SkillState skillState = player.skillsDict[skillID];
		elementUnlockCount[skillState.element]++;
		SpellBookUI.SkillEquipType skillEquipType2 = SpellBookUI.SkillEquipType.Optional;
		if (skillState.isBasic)
		{
			skillEquipType2 = SpellBookUI.SkillEquipType.Basic;
			skillTypeUnlockCount[skillEquipType2]++;
		}
		else if (skillState.isDash)
		{
			skillEquipType2 = SpellBookUI.SkillEquipType.Dash;
			skillTypeUnlockCount[skillEquipType2]++;
		}
		else
		{
			if (baseUnlocked)
			{
				skillEquipType2 = SpellBookUI.SkillEquipType.Optional;
				skillTypeUnlockCount[skillEquipType2]++;
			}
			if (sigUnlocked)
			{
				skillEquipType2 = SpellBookUI.SkillEquipType.Signature;
				skillTypeUnlockCount[skillEquipType2]++;
			}
		}
		newSpells[skillID] = new NewSpellRecord(skillID, element, baseUnlocked, sigUnlocked, skillEquipType2);
	}

	public void Remove(string skillID, bool sig)
	{
		if (!newSpells.ContainsKey(skillID))
		{
			return;
		}
		NewSpellRecord newSpellRecord = newSpells[skillID];
		if (newSpellRecord.sigUnlocked && newSpellRecord.baseUnlocked)
		{
			if (sig)
			{
				newSpellRecord.sigUnlocked = false;
				skillTypeUnlockCount[SpellBookUI.SkillEquipType.Signature]--;
				newSpellRecord.skillType = SpellBookUI.SkillEquipType.Optional;
			}
			else
			{
				newSpellRecord.baseUnlocked = false;
				skillTypeUnlockCount[SpellBookUI.SkillEquipType.Optional]--;
				newSpellRecord.skillType = SpellBookUI.SkillEquipType.Signature;
			}
		}
		else if ((!sig || newSpellRecord.sigUnlocked) && (sig || newSpellRecord.baseUnlocked))
		{
			if (newSpellRecord.skillType == SpellBookUI.SkillEquipType.Basic)
			{
				skillTypeUnlockCount[SpellBookUI.SkillEquipType.Basic]--;
			}
			else if (newSpellRecord.skillType == SpellBookUI.SkillEquipType.Dash)
			{
				skillTypeUnlockCount[SpellBookUI.SkillEquipType.Dash]--;
			}
			else if (newSpellRecord.skillType == SpellBookUI.SkillEquipType.Signature)
			{
				skillTypeUnlockCount[SpellBookUI.SkillEquipType.Signature]--;
			}
			else if (newSpellRecord.baseUnlocked)
			{
				skillTypeUnlockCount[SpellBookUI.SkillEquipType.Optional]--;
			}
			elementUnlockCount[newSpellRecord.element]--;
			newSpells.Remove(skillID);
		}
	}

	public void Reset()
	{
		if (elementUnlockCount != null)
		{
			elementUnlockCount[ElementType.Chaos] = 0;
			elementUnlockCount[ElementType.Earth] = 0;
			elementUnlockCount[ElementType.Fire] = 0;
			elementUnlockCount[ElementType.Air] = 0;
			elementUnlockCount[ElementType.Water] = 0;
			elementUnlockCount[ElementType.Lightning] = 0;
		}
		if (skillTypeUnlockCount != null)
		{
			skillTypeUnlockCount[SpellBookUI.SkillEquipType.Basic] = 0;
			skillTypeUnlockCount[SpellBookUI.SkillEquipType.Dash] = 0;
			skillTypeUnlockCount[SpellBookUI.SkillEquipType.Optional] = 0;
			skillTypeUnlockCount[SpellBookUI.SkillEquipType.Signature] = 0;
		}
		newSpells.Clear();
	}
}
public class NewSpellRecord
{
	public string skillID;

	public ElementType element;

	public bool baseUnlocked;

	public bool sigUnlocked;

	public SpellBookUI.SkillEquipType skillType;

	public NewSpellRecord(string skillID, ElementType element, bool baseUnlocked, bool sigUnlocked, SpellBookUI.SkillEquipType skillEquipType)
	{
		this.skillID = skillID;
		this.element = element;
		this.baseUnlocked = baseUnlocked;
		this.sigUnlocked = sigUnlocked;
		skillType = skillEquipType;
	}

	public bool IsSkillType(SpellBookUI.SkillEquipType testSkillType)
	{
		return testSkillType switch
		{
			SpellBookUI.SkillEquipType.Dash => skillType == SpellBookUI.SkillEquipType.Dash, 
			SpellBookUI.SkillEquipType.Basic => skillType == SpellBookUI.SkillEquipType.Basic, 
			SpellBookUI.SkillEquipType.Signature => sigUnlocked, 
			SpellBookUI.SkillEquipType.Optional => baseUnlocked, 
			_ => false, 
		};
	}
}
