using UnityEngine.UI;

public class SkillSelectionUI : MonoBehaviour
{
	public Player currentPlayer;

	public bool hasFocus;

	public bool skillClicked;

	public string elementType;

	public Sprite elementSprite;

	public Player.SkillState selectedSkill;

	private GameObject skillEntryPrefab;

	private Text TitleText;

	private Image TitleIcon;

	private Transform skillsParent;

	private ScrollRect skillsScrollRect;

	private List<Player.SkillState> elementSkillList = new List<Player.SkillState>();

	private List<KeyValuePair<Player.SkillState, GameObject>> skillsList = new List<KeyValuePair<Player.SkillState, GameObject>>();

	private List<SkillEntryUI> skillEntriesList = new List<SkillEntryUI>();

	private int skillsPerRow = 3;

	private int skillsPerColumn = 3;

	private int currentIndex;

	private int prevIndex;

	private Color defaultColor = new Color(0.863f, 0.804f, 0.588f);

	private Color selectedColor = new Color(0.6f, 0.6f, 0.6f);

	private Vector2 cursorVector;

	private bool inputReceived;

	public void LoadSkills(bool updateOnly = false)
	{
		skillEntryPrefab = ChaosBundle.Get("Assets/Prefabs/UI/SkillStore/SkillEntryTemplate.prefab");
		TitleText = base.transform.Find("TitleBar/ElementName").GetComponent<Text>();
		TitleText.text = "<b>" + elementType + "</b>";
		TitleIcon = base.transform.Find("TitleBar/ElementIcon").GetComponent<Image>();
		TitleIcon.sprite = elementSprite;
		skillsParent = base.transform.Find("SkillsWindow/SkillsList") as RectTransform;
		skillsScrollRect = base.transform.Find("SkillsWindow").GetComponent<ScrollRect>();
		foreach (Transform item in skillsParent)
		{
			if (item != skillsParent)
			{
				Object.Destroy(item.gameObject);
			}
		}
		elementSkillList.Clear();
		foreach (Player.SkillState value in currentPlayer.skillsDict.Values)
		{
			if (value.element.ToString() == elementType)
			{
				elementSkillList.Add(value);
			}
		}
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		float num4 = 1f / (float)skillsPerRow;
		float num5 = 1f / (float)skillsPerColumn;
		skillsList.Clear();
		skillEntriesList.Clear();
		foreach (Player.SkillState elementSkill in elementSkillList)
		{
			GameObject gameObject = Object.Instantiate(skillEntryPrefab, Vector3.zero, Quaternion.identity);
			skillsList.Add(new KeyValuePair<Player.SkillState, GameObject>(elementSkill, gameObject));
			gameObject.transform.SetParent(skillsParent);
			SkillEntryUI component = gameObject.GetComponent<SkillEntryUI>();
			component.skill = elementSkill;
			component.wasPressed = false;
			skillEntriesList.Add(component);
			gameObject.transform.Find("Icon").GetComponent<Image>().sprite = IconManager.GetSkillIcon(elementSkill.skillID);
			gameObject.transform.Find("Name").GetComponent<Text>().text = TextManager.GetSkillName(elementSkill.skillID);
			if (elementSkill.currentLevel < 1)
			{
				gameObject.transform.Find("Level").GetComponent<Text>().text = "Not Owned";
			}
			else
			{
				gameObject.transform.Find("Level").GetComponent<Text>().text = "Level " + elementSkill.currentLevel;
			}
			if (elementSkill.currentLevel != SkillStats.maxSkillLevel)
			{
				gameObject.transform.Find("Gold").GetComponent<Text>().text = elementSkill.skillData.GetValue<int>("goldCost", elementSkill.currentLevel + 1).ToString();
			}
			else
			{
				gameObject.transform.Find("Gold").GetComponent<Text>().text = "MAX";
			}
			RectTransform component2 = gameObject.GetComponent<RectTransform>();
			component2.offsetMin = Vector2.zero;
			component2.offsetMax = Vector2.zero;
			if (num % 3 == 0 && num > 0)
			{
				num2 = 0;
				num3++;
			}
			component2.anchorMin = new Vector2(num4 * (float)num2, 1f - num5 * (float)(num3 + 1));
			component2.anchorMax = new Vector2(num4 * (float)(num2 + 1), 1f - num5 * (float)num3);
			num2++;
			num++;
		}
		if (!updateOnly)
		{
			currentIndex = 0;
			prevIndex = 0;
		}
		SelectSkill(currentIndex);
		inputReceived = true;
		skillClicked = false;
	}

	private void Update()
	{
		if (hasFocus && !skillClicked)
		{
			if (CheckForSkillClicked())
			{
				skillClicked = true;
			}
			HandleNavigation();
		}
	}

	private bool CheckForSkillClicked()
	{
		if (!currentPlayer.IsKeyboardInput)
		{
			return false;
		}
		for (int i = 0; i < skillEntriesList.Count; i++)
		{
			if (skillEntriesList[i].wasPressed)
			{
				skillEntriesList[i].wasPressed = false;
				prevIndex = currentIndex;
				currentIndex = i;
				SelectSkill(currentIndex);
				return true;
			}
		}
		return false;
	}

	private void HandleNavigation()
	{
		cursorVector = currentPlayer.inputDevice.GetMoveVector();
		if (inputReceived && cursorVector.magnitude < 0.2f)
		{
			inputReceived = false;
		}
		else
		{
			if (inputReceived || !(cursorVector.magnitude > 0.3f))
			{
				return;
			}
			SoundManager.PlayAudio("MenuMove");
			inputReceived = true;
			prevIndex = currentIndex;
			if (Mathf.Abs(cursorVector.x) > Mathf.Abs(cursorVector.y))
			{
				if (cursorVector.x > 0f)
				{
					currentIndex++;
					if (currentIndex % 3 == 0)
					{
						currentIndex -= 3;
					}
					if (currentIndex < 0)
					{
						currentIndex = 0;
					}
					else if (currentIndex == skillsList.Count)
					{
						currentIndex = Mathf.FloorToInt((skillsList.Count - 1) / skillsPerRow) * skillsPerRow;
					}
				}
				else
				{
					currentIndex--;
					if ((currentIndex + 1) % skillsPerRow == 0)
					{
						currentIndex += skillsPerRow;
					}
					if (currentIndex > skillsList.Count - 1)
					{
						currentIndex = skillsList.Count - 1;
					}
				}
			}
			else if (cursorVector.y > 0f)
			{
				currentIndex -= skillsPerRow;
				if (currentIndex < 0)
				{
					currentIndex = Mathf.FloorToInt((skillsList.Count - 1) / skillsPerRow) * skillsPerRow + (currentIndex + skillsPerRow) % skillsPerRow;
				}
				if (currentIndex > skillsList.Count - 1)
				{
					currentIndex = (Mathf.FloorToInt((skillsList.Count - 1) / skillsPerRow) - 1) * skillsPerRow + (currentIndex + skillsPerRow) % skillsPerRow;
				}
			}
			else
			{
				currentIndex += skillsPerRow;
				if (currentIndex > skillsList.Count - 1)
				{
					currentIndex = (currentIndex + skillsPerRow) % skillsPerRow;
				}
			}
			SelectSkill(currentIndex);
		}
	}

	private void SelectSkill(int index)
	{
		skillsScrollRect.verticalNormalizedPosition = 1f;
		selectedSkill = skillsList[index].Key;
		skillsList[prevIndex].Value.GetComponent<Image>().color = defaultColor;
		skillsList[index].Value.GetComponent<Image>().color = selectedColor;
		if (skillsList.Count > skillsPerRow * 2)
		{
			float num = Mathf.Floor(index / skillsPerRow);
			num /= Mathf.Ceil(skillsList.Count / skillsPerRow);
			num *= (float)(Mathf.CeilToInt(skillsList.Count / skillsPerRow) * skillsPerRow);
			num = 1f - num;
			skillsScrollRect.verticalNormalizedPosition = num;
		}
	}

	public void UpdateSkill(Player.SkillState selectedSkill)
	{
		foreach (KeyValuePair<Player.SkillState, GameObject> skills in skillsList)
		{
			if (selectedSkill.skillID == skills.Key.skillID)
			{
				skills.Value.transform.Find("Level").GetComponent<Text>().text = "Level " + skills.Key.currentLevel;
				if (selectedSkill.currentLevel != SkillStats.maxSkillLevel)
				{
					skills.Value.transform.Find("Gold").GetComponent<Text>().text = selectedSkill.skillData.GetValue<int>("goldCost", selectedSkill.currentLevel + 1).ToString();
				}
				else
				{
					skills.Value.transform.Find("Gold").GetComponent<Text>().text = "MAX";
				}
			}
		}
	}
}
