		elementsParent = transform.Find("Elements");
		cursorTrans = transform.Find("Elements/Cursor").GetComponent<RectTransform>();
		cursorOrigin = cursorTrans.position;
		elementTitleText = transform.Find("Description/Title").GetComponent<Text>();
		elementDescriptionText = transform.Find("Description/Text").GetComponent<Text>();
		elementDescriptionText.text = string.Empty;
		elementSprites = new Dictionary<string, Sprite>
		{
			{ "Chaos", chaosSprite },
			{ "Fire", fireSprite },
			{ "Water", waterSprite },
			{ "Air", airSprite },
			{ "Lightning", lightningSprite },
			{ "Earth", earthSprite }
		};
	}

	public void LoadElements()
	{
		elementCounts.Clear();
		elementTotals.Clear();
		elementEntryLocations.Clear();
		elementEntriesList.Clear();
		foreach (Transform item in elementsParent)
		{
			if (item != elementsParent && item != cursorTrans)
			{
				UnityEngine.Object.Destroy(item.gameObject);
			}
		}
		float num = (float)Screen.height / 6f;
		float num2 = num * 0.75f;
		cursorTrans.sizeDelta = Vector2.one * num;
		foreach (Player.SkillState value in currentPlayer.skillsDict.Values)
		{
			if (!elementCounts.ContainsKey(value.element))
			{
				elementCounts.Add(value.element, 0);
			}
			if (!elementTotals.ContainsKey(value.element))
			{
				elementTotals.Add(value.element, 0);
			}
			if (value.currentLevel > 0)
			{
				elementCounts[value.element]++;
			}
			elementTotals[value.element]++;
		}
		float num3 = (float)Math.PI * 2f / (float)elementTotals.Count;
		float num4 = (float)Math.PI / 2f;
		foreach (KeyValuePair<ElementType, int> elementTotal in elementTotals)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(elementEntryPrefab, Vector3.zero, Quaternion.identity);
			gameObject.name = elementTotal.Key.ToString();
			gameObject.transform.SetParent(elementsParent);
			RectTransform component = gameObject.GetComponent<RectTransform>();
			component.anchoredPosition = new Vector2(Mathf.Cos(num4), Mathf.Sin(num4)) * num;
			component.sizeDelta = Vector2.one * num2;
			elementEntryLocations.Add(component.anchoredPosition, gameObject);
			num4 -= num3;
			gameObject.transform.Find("Icon").GetComponent<Image>().sprite = elementSprites[elementTotal.Key.ToString()];
			gameObject.transform.Find("Progression").GetComponent<Text>().text = elementCounts[elementTotal.Key] + "/" + elementTotal.Value;
			ElementEntryUI component2 = gameObject.GetComponent<ElementEntryUI>();
			component2.element = elementTotal.Key;
			component2.wasPressed = false;
			elementEntriesList.Add(component2);
		}
		elementClicked = false;
	}

	private void Update()
	{
		if (!hasFocus || elementClicked)
		{
			return;
		}
		cursorVector = currentPlayer.inputDevice.GetMoveVector();
		if (cursorVector.magnitude < 0.5f && !elementClicked)
		{
			selectedElement = null;
			elementTitleText.text = "Select an element!";
			cursorTrans.position = cursorOrigin;
		}
		else
		{
			cursorTrans.gameObject.SetActive(value: true);
			float num = 9999f;
			float num2 = 0f;
			foreach (KeyValuePair<Vector2, GameObject> elementEntryLocation in elementEntryLocations)
			{
				num2 = Vector2.Distance(cursorVector, elementEntryLocation.Key);
				if (num2 < num)
				{
					num = num2;
					selectedElement = elementEntryLocation.Value;
					cursorTrans.anchoredPosition = elementEntryLocation.Key;
				}
			}
			elementTitleText.text = "<b>" + selectedElement.name + "</b>";
		}
		if (!currentPlayer.IsKeyboardInput)
		{
			return;
		}
		foreach (ElementEntryUI elementEntries in elementEntriesList)
		{
			if (elementEntries.wasPressed)
			{
				elementEntries.wasPressed = false;
				selectedElement = elementEntries.gameObject;
				elementClicked = true;
			}
		}
	}
}
using UnityEngine;
using UnityEngine.UI;

public class StockSkillUI : MonoBehaviour
{
	private Player player;

	public Sprite[] skillBGSprites;

	private bool stockSkillAvailable;

	private bool refreshQueued = true;

	private Image stockSkillImage;

	private Image stockSkillButtonImage;

	private Image stockSkillBG;

	private Image stockSkillBGOverlay;

	private Text equipPrompt;

	public Image mapBG;

	public Image mapBGOverlay;

	public Image mapButtonImage;

	public Text mapPrompt;

	private string currentStockSkillID;

	public void Claim(Player newPlayer)
	{
		player = newPlayer;
		RefreshUI();
	}

	public void RefreshUI()
	{
		if (!(player == null))
		{
			refreshQueued = true;
			stockSkillButtonImage.sprite = GameUI.GetInputSprite(player.inputDevice.inputScheme, "EquipMenu");
			if (player.stockSkill != null)
			{
				Image image = stockSkillBG;
				Sprite sprite;
				if (player.stockSkill.isSignature)
				{
					sprite = skillBGSprites[4];
				}
				else
				{
					sprite = ((!player.stockSkill.IsEmpowered) ? skillBGSprites[0] : skillBGSprites[2]);
				}
				image.sprite = sprite;
			}
			mapButtonImage.sprite = GameUI.GetInputSprite(player.inputDevice.inputScheme, "Map");
		}
	}

	public void Release()
	{
		player = null;
	}

	private void Awake()
	{
		player = null;
		stockSkillImage = transform.Find("SkillEntry/SkillIcon").GetComponent<Image>();
		stockSkillButtonImage = transform.Find("SkillButton").GetComponent<Image>();
		stockSkillBG = transform.Find("SkillEntry/SkillBG").GetComponent<Image>();
		stockSkillBGOverlay = transform.Find("SkillEntry/SkillBGOverlay").GetComponent<Image>();
		equipPrompt = transform.Find("EquipPrompt").GetComponent<Text>();
		TextManager.AddUIRef("playerMenu-buttonPrompt", equipPrompt);
		mapBG = transform.Find("MapEntry/MapBG").GetComponent<Image>();
		mapBGOverlay = transform.Find("MapEntry/MapBGOverlay").GetComponent<Image>();
		mapButtonImage = transform.Find("MapButton").GetComponent<Image>();
		mapPrompt = transform.Find("MapPrompt").GetComponent<Text>();
		TextManager.AddUIRef("keyConfigMenu-map", mapPrompt);
		Disable();
	}

	private void Update()
	{
		if (!refreshQueued || player == null)
		{
			return;
		}
		refreshQueued = false;
		if (player.stockSkill == null)
		{
			if (stockSkillAvailable)
			{
				Disable();
			}
		}
		else
		{
			if (!stockSkillAvailable || currentStockSkillID != player.stockSkill.skillID)
			{
				Activate();
			}
			currentStockSkillID = player.stockSkill.skillID;
		}
		ToggleMap(Globals.InGameScene(string.Empty) && !Application.loadedLevelName.Contains("Boss"));
	}

	private void ToggleMap(bool givenStatus)
	{
		if (givenStatus)
		{
			mapBGOverlay.enabled = false;
			mapBG.color = CooldownUI.readyBorderColor;
			mapButtonImage.color = CooldownUI.transparent;
			mapPrompt.color = CooldownUI.transparent;
		}
		else
		{
			mapBGOverlay.enabled = true;
			mapBG.color = CooldownUI.notReadyBorderColor;
			mapButtonImage.color = CooldownUI.darkened;
			mapPrompt.color = CooldownUI.darkened;
		}
	}

	private void Activate()
	{
		stockSkillAvailable = true;
		stockSkillBGOverlay.enabled = false;
		stockSkillBG.color = CooldownUI.readyBorderColor;
		stockSkillImage.sprite = IconManager.GetSkillIcon(player.stockSkill.skillID);
		stockSkillButtonImage.color = CooldownUI.transparent;
		equipPrompt.color = CooldownUI.transparent;
	}

	private void Disable()
	{
		stockSkillAvailable = false;
		stockSkillBGOverlay.enabled = true;
		stockSkillBG.color = CooldownUI.notReadyBorderColor;
		stockSkillImage.sprite = IconManager.GetSkillIcon("Disabled");
		stockSkillButtonImage.color = CooldownUI.transparent;
		equipPrompt.color = CooldownUI.transparent;
	}
}
