public void HandleOverdrive()
{
	if (overdriveSkillRef != null)
	{
		if (fsm.currentStateName != overdriveSkillRef.skillID)
		{
			overdriveSkillRef.isUltimate = false;
			overdriveSkillRef = null;
			if (overdriveCard != null)
			{
				overdriveCard.ForceFadeOut();
			}
		}
		else if (overdriveCard != null)
		{
			overdriveCard.transform.position = transform.position + new Vector3(0f, 2.125f, 0f);
		}
	}
	if (!overdriveReady)
	{
		if (OverdriveProgress >= 100f)
		{
			overdriveReady = true;
			AnnounceOverdriveEvent(ready: true);
			ToggleOverdriveEffects(status: true);
			overdriveEffects.Burst(10, local: true, activation: false);
			spriteMaterial.SetColor("_OutlineColor", OutlineColor);
			spriteMaterial.SetColor("_OutlineColor2", OutlineColor2);
			curOverdriveDecayRate = overdriveActiveDecayRate;
			overdriveSkillRef = GetSignatureSkill();
			if (overdriveSkillRef != null)
			{
				overdriveSkillRef.cooldownRef.Reset();
			}
			overdriveSkillRef = null;
			overdriveDoubleUsed = false;
			return;
		}
	}
	else
	{
		if (OverdriveProgress <= overdriveMinValue)
		{
			overdriveReady = false;
			AnnounceOverdriveEvent(ready: false, overdriveTimedOut);
			ToggleOverdriveEffects(status: false);
			spriteMaterial.SetColor("_OutlineColor", OutlineColorDisabled);
			spriteMaterial.SetColor("_OutlineColor2", OutlineColor2Disabled);
			curOverdriveDecayRate = overdriveBuildDecayRate;
			overdriveTimedOut = true;
			if (!LoadingScreen.loading && !(Time.timeScale < 1f))
			{
				SoundManager.PlayAudio("PlayerOverdriveExpire");
			}
			return;
		}
		overdriveSkillRef = GetSignatureSkill();
		if (!airborneStat.CurrentValue && overdriveSkillRef != null && overdriveSkillRef.IsOverdriveReady() && inputDevice.GetButton("Skill" + overdriveSkillRef.skillSlot) && fsm.currentStateName != overdriveSkillRef.skillID && fsm.currentStateName != "Dead" && fsm.currentStateName != "Fall" && fsm.currentStateName != "Frozen" && fsm.currentStateName != "Paused" && fsm.currentStateName != "TeleToLoc" && health.CurrentHealthValue > 0)
		{
			if (overdriveResetsCD.CurrentValue)
			{
				cooldownManager.ResetCooldowns();
				hud.MiscPing("HourglassUI");
			}
			if (overdriveForceInstead.CurrentValue)
			{
				if (overdriveDoubleStat.CurrentValue && !overdriveDoubleUsed)
				{
					overdriveDoubleUsed = true;
					odPauseStopwatch.IsRunning = true;
				}
				else
				{
					ForceOverdriveExpire();
				}
				if (overdriveHealsInstead.CurrentValue)
				{
					health.RestoreHealth(overdriveHealValue);
					SoundManager.PlayAudio("Powerup");
					UnityEngine.Object.Instantiate(HealthPowerup.EffectPrefab, transform.position, Quaternion.identity, transform);
				}
				return;
			}
			TimeScaleController.StandardFreezeIntoEaseOutTimeScale();
			health.SetInvulnerabilityDuration(overdriveInvincibleTime, showMsg: false);
			overdriveEffects.Burst();
			dustEmitter.EmitCircle(80, 1.5f, 22f);
			overdriveSkillRef.isUltimate = true;
			fsm.QueueChangeState(overdriveSkillRef.skillID);
			CameraController.ShakeCamera();
			if (overdriveDoubleStat.CurrentValue && !overdriveDoubleUsed)
			{
				overdriveDoubleUsed = true;
				odPauseStopwatch.IsRunning = true;
			}
			else if (overdriveMultiStat.CurrentValue && overdriveRaffleStat.CurrentValue > UnityEngine.Random.value)
			{
				odPauseStopwatch.IsRunning = true;
			}
			else
			{
				OverdriveProgress = overdriveMinValue;
				overdriveTimedOut = false;
			}
		}
	}
	if (!odPauseStopwatch.IsRunning && OverdriveProgress > overdriveMinValue)
	{
		OverdriveProgress -= Time.deltaTime * curOverdriveDecayRate.CurrentValue;
	}
}

