	public virtual void Update()
	{
		if (!shootAnnounced && moveSpeed > 0f && moveVector != Vector2.zero && projectileShootEvent != null)
		{
			projectileShootEvent(this);
			shootAnnounced = true;
		}
		if (CheckMaxLifeTime())
		{
			return;
		}
		if (ChaosStopwatch.Check(flyStopwatchID))
		{
			if (!boomerang)
			{
				ResetProjectile();
				return;
			}
			if (parentObject == null)
			{
				boomerang = false;
				Debug.Log(gameObject.name + " has no parent, but is set to boomerang.");
				return;
			}
			if (!boomerangReturning)
			{
				boomerangReturning = true;
				OnBoomerangReturn();
				return;
			}
			if (attackBox != null && resetAttackOnBoomerangReturn)
			{
				attackBox.gameObject.SetActive(value: true);
			}
			HandleBoomerang();
		}
		if (boomerangReturning && (parentObject == null || Vector2.Distance(transform.position, parentObject.transform.position) < returningSnapDistance))
		{
			ResetProjectile();
		}
	}

	public virtual void FixedUpdate()
	{
