	public void HandlePointTowardMoveVector()
	{
		if (pointTowardMoveVector && moveVector != Vector2.zero && !isPointedAtMoveVector)
		{
			Vector2 targetPosition = ((!flipPointTowardMoveVector) ? ((Vector2)transform.position + moveVector) : ((Vector2)transform.position - moveVector));
			RotateTowardsTarget(targetPosition);
			isPointedAtMoveVector = true;
		}
		if (pointTowardMoveVector && isPointedAtMoveVector && !visualsOn)
		{
			Show();
		}
	}

	public bool IsParentObject(GameObject other)
	{
		Entity componentInParent = other.GetComponentInParent<Entity>();
		return other == parentObject || other.transform.parent.gameObject == parentObject || (componentInParent != null && componentInParent.skillCategory == attackBox.atkInfo.skillCategory) || (parentEntity != null && componentInParent == parentEntity);
	}

	public virtual void OnTriggerEnter2D(Collider2D other)
	{
