		rigidbody2D = GetComponent<Rigidbody2D>();
		anim = GetComponent<Animator>();
		fall = GetComponentInChildren<Fall>();
		spriteRenderer = GetComponentInChildren<SpriteRenderer>();
		if (spriteRenderer != null)
		{
			spriteTrans = spriteRenderer.transform;
		}
		Transform transform = base.transform.Find("FloorContact");
		if (transform != null)
		{
			floorContact = transform.gameObject;
		}
		layerMask = ChaosCollisions.layerAllWallAndObst;
		targetPosition = base.transform.position;
		heightOffsetPosition = base.transform.position;
		ignoreFallMod = new BoolVarStatMod(gameObject.name + "thrownItem", newModValue: true, 3);
	}

	public virtual void Start()
	{
		if (initiateOnStart)
		{
			InitThrow();
		}
	}

	public virtual void Update()
	{
	}

	public virtual void FixedUpdate()
	{
		if (!throwInitiated || throwComplete)
		{
			return;
		}
		if (!ignoreLineLerpPosition)
		{
			rigidbody2D.MovePosition(lineLerpPosition);
		}
		spriteTrans.localPosition = heightOffsetPosition;
		if (throwCompletedLastFrame)
		{
			throwCompletedLastFrame = false;
			frameDelayActive = true;
			return;
		}
		if (frameDelayActive)
		{
			frameDelayActive = false;
			throwComplete = true;
			if (fall != null)
			{
				fall.ignoreFall.RemoveMod(ignoreFallMod);
			}
			if (spriteTrans != null)
			{
				spriteStartPosition.y = landedHeight;
				spriteTrans.localPosition = spriteStartPosition;
			}
			OnLanding();
			return;
		}
		percentComplete = ChaosStopwatch.GetTimePercentage(flightStopwatchID);
		throwCompletedLastFrame = percentComplete >= 1f;
		if (!ignoreLineLerpPosition)
		{
			lineLerpPosition = Vector3.Lerp(startPosition, targetPosition, percentComplete);
		}
		if (!isFalling)
		{
			isFalling = percentComplete >= isFallingThreshold;
		}
		relativePercentValue = Mathf.Clamp01(Mathf.Abs(percentComplete - isFallingThreshold) / ((!isFalling) ? isFallingThreshold : isFallingComplement));
		if (useParabolic)
		{
			relativePercentValue *= relativePercentValue;
		}
		heightLerpValue = Mathf.Lerp(calcThrowHeight, (!isFalling) ? spriteStartPosition.y : landedHeight, relativePercentValue);
		heightOffsetPosition.y = heightLerpValue;
		HandleRotateSprite();
	}

	public virtual void HandleRotateSprite()
	{
		if (rotateSprite)
		{
			spriteTrans.transform.localEulerAngles = Vector3.Lerp(startRotation, endRotation, percentComplete);
		}
	}

	public virtual void OnLanding()
	{
		if (onLandingEventHandlers != null)
		{
			onLandingEventHandlers();
		}
		if (updateFloorContact && enableFloorContactOnLanding && floorContact != null)
		{
			floorContact.SetActive(value: true);
		}
		if (destroyAfterLanding && gameObject != null)
		{
			Object.Destroy(gameObject, destroyTime);
		}
	}

	public Vector2 GetLineCastTargetPosition(Vector3 startPos, Vector3 endPos)
	{
		if (Physics2D.LinecastNonAlloc(startPos, endPos, castResults, layerMask) == 0)
		{
			return endPos;
		}
		return startPos + (endPos - startPos).normalized * castResults[0].distance;
	}

	public virtual void InitThrow()
	{
		startPosition = transform.position;
		SetSpriteVars(spriteTrans);
		if (updateFloorContact && floorContact != null)
		{
			floorContact.SetActive(value: false);
		}
		if (useLineCastPosition)
		{
			targetPosition = GetLineCastTargetPosition(startPosition, targetPosition);
		}
		if (randomOffset > 0f)
		{
			Vector2 vec = targetPosition;
			float radius = randomOffset;
			targetPosition = vec.Randomize(1f, radius);
		}
		if (useCalculatedValues)
		{
			calcMultiplier = Vector2.Distance(startPosition, targetPosition) / moveSpeed;
			calcFlightTime = baseFlightTime * calcMultiplier;
			calcThrowHeight = Mathf.Max(0.05f, 2f * throwHeight * calcMultiplier * scaledHeightModifier);
		}
		else
		{
			calcMultiplier = 1f;
			calcFlightTime = baseFlightTime;
			calcThrowHeight = throwHeight;
		}
		flightStopwatchID = ChaosStopwatch.Begin(calcFlightTime);
		isFallingComplement = Mathf.Max(1f - isFallingThreshold, 0.01f);
		if (fall != null)
		{
			fall.ignoreFall.AddMod(ignoreFallMod);
		}
		throwComplete = false;
		throwInitiated = true;
		isFalling = false;
		throwCompletedLastFrame = false;
		frameDelayActive = false;
		lineLerpPosition = transform.position;
		heightOffsetPosition = spriteStartPosition;
		if (rotateSprite)
		{
			startRotation = spriteTrans.localEulerAngles;
			endRotation = startRotation;
			endRotation.z += ((!(targetPosition.x < transform.position.x)) ? (-360f * rotationCount) : (360f * rotationCount));
			if (reverseRotation)
			{
				endRotation.z = 0f - endRotation.z;
			}
		}
	}

	public void PauseThrow()
	{
		ChaosStopwatch.Pause(flightStopwatchID);
	}

	public void ResumeThrow()
	{
		ChaosStopwatch.Resume(flightStopwatchID);
	}

	public virtual void EndThrow(Vector2? givenLocation)
	{
		if (givenLocation.HasValue)
		{
			targetPosition = givenLocation.Value;
		}
		ChaosStopwatch.Stop(flightStopwatchID);
	}

	public virtual void SetSpriteVars(Transform givenTrans)
	{
		if (givenTrans == null)
		{
			Debug.Log("Sprite not set for thrown item! : " + gameObject.name);
			return;
		}
		if (spriteStartPosition == Vector3.zero)
		{
			spriteStartPosition = givenTrans.localPosition;
		}
		if (landedHeight == -10f)
		{
			landedHeight = givenTrans.localPosition.y;
		}
	}

	public virtual void ThrowToTargetVector(Vector2 givenPosition)
	{
		targetPosition = givenPosition;
		InitThrow();
	}

	public virtual void ForceNewHeights(float givenStart, float givenEnd = 0f)
	{
		spriteStartPosition = Vector2.up * givenStart;
		heightOffsetPosition = spriteStartPosition;
		spriteTrans.transform.localPosition = spriteStartPosition;
		landedHeight = givenEnd;
	}
}
