	public virtual bool HandleTeleportToPlayer(Vector2 givenPosition, bool forceMove = false)
	{
		if (forceMove || Vector2.Distance(transform.position, givenPosition) > teleportToPlayerRange)
		{
			PlaySpawnEffect(transform.position);
			transform.position = givenPosition;
			Vector2 startPos = givenPosition;
			Vector2 vec = givenPosition;
			float radius = teleportDiff;
			givenPosition = Globals.GetLinecastVector(startPos, vec.Randomize(1f, radius), ChaosCollisions.layerAllWallAndObst);
			rigidbody2D.MovePosition(givenPosition);
			PlaySpawnEffect(givenPosition);
			return true;
		}
		return false;
	}

	public virtual TargetInfo UpdateTargetInfo()
	{
		return closestTargetInfo = Entity.GetClosestTarget(Entity.GetAllTargetsInRange(targetList, parentTrans.position, maxDistToParent + attackRadius, playerTagOnly: false, parentSummonList), transform.position, maxDistToParent * 2.5f, playerTagOnly: false, parentSummonList);
	}

	public virtual void DestroyMinion()
	{
		fsm.QueueChangeState("Dead");
	}

	public bool MoveToTargetOrFollowPath(Vector3 startPos, Vector3 targetPos, float losRange, float moveToRadius = 0f, string moveAnimName = "Run")
	{
		if (Entity.HasLineOfSight(startPos, targetPos, losRange, lineOfSightLayerMask))
		{
			ChaosStopwatch.Stop(requestPathStopwatchID);
			if (moveAnimName != string.Empty)
			{
				PlayAnimOnFaceDirChange(moveAnimName, targetPos, animFacingDirections, appendFacingDirection: false);
			}
			if (movement.MoveToTarget(targetPos, moveToRadius))
			{
				FaceTarget(targetPos, animFacingDirections);
				return true;
			}
			return false;
		}
		if (ChaosStopwatch.Check(requestPathStopwatchID))
		{
			requestPathStopwatchID = ChaosStopwatch.Begin(requestPathTime);
			followingPath = false;
			if (FindAndTraversePath(traversableNodeMap, startPos, targetPos, minNodeDist, moveAnimName, appendFacingDirection: false, animFacingDirections, startNew: true) == -1)
			{
				return true;
			}
			followingPath = true;
			return false;
		}
		if (followingPath && FindAndTraversePath(traversableNodeMap, startPos, targetPos, minNodeDist, moveAnimName, appendFacingDirection: false, animFacingDirections) != 0)
		{
			followingPath = false;
			return true;
		}
		return false;
	}

	public bool CanApproachTarget(Vector3 startPos, Vector3 targetPos, float maxDist)
	{
		return Entity.HasLineOfSight(startPos, targetPos, maxDist, lineOfSightLayerMask) || Pathfinder.GetPath(traversableNodeMap, targetPos, startPos, lineOfSightLayerMask) != null;
	}

	public void PlayMoveAudio()
	{
		if (moveAudioID != string.Empty && !moveAudioStopwatch.IsRunning)
		{
			moveAudioStopwatch.IsRunning = true;
			SoundManager.PlayWithDistAndSPR(moveAudioID, transform.position);
		}
	}
