		public ChaosMinionIdleState(string newName, FSM newFSM, ChaosMinion newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}
		public override void OnFollow()
		{
			if (!parent.isUltimate || !ultStopwatch.IsRunning)
			{
				base.OnFollow();
			}
		}
		public override void OnChase()
		{
			if (parent.isUltimate)
			{
				if (ultStopwatch.IsRunning)
				{
					return;
				}
				ultStopwatch.IsRunning = true;
				if (ChaosStopwatch.GetRemainingTime(parent.durationStopwatchID) < 0.75f)
				{
					return;
				}
				attackPosition = parent.coreTrans.position;
				(ultList = parent.GetTargetsInRange()).Shuffle();
				for (int num = ultList.Count - 1; num >= 0; num--)
				{
					if (!(ultList[num] == null))
					{
						targetPosition = Entity.GetTargetInfoFromObject(ultList[num]).hurtBoxPosition;
						if (Entity.HasLineOfSight(attackPosition, targetPosition, parent.maxDistToParent + parent.attackRadius, ChaosCollisions.layerUpperWallAndObst))
						{
							parent.CreateLaserBeam(attackPosition, (targetPosition - attackPosition).normalized).AutoBlast(0.35f);
							parent.anim.Play("Attack", -1, 0f);
						}
						if (Globals.RandBool)
						{
							break;
						}
					}
				}
			}
			else
			{
				base.OnChase();
			}
		}
