		{
			if (!ChaosStopwatch.Check(delayStopwatchID))
			{
				return;
			}
			if (!blastCompleted)
			{
				blastCompleted = true;
				delayStopwatchID = ChaosStopwatch.Begin(Random.Range(0.6f, 0.9f));
				parent.anim.Play("Attack", -1, 0f);
				parent.movement.moveVector = -targetVector;
				parent.movement.MoveToMoveVector(parent.movement.dashSpeedStat.CurrentValue);
				if (currentLB != null)
				{
					currentLB.Blast();
				}
			}
			else
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
