public class UseSeekers : SkillState
{
	public GameObject seekerPrefab;

	public float throwRange = 1.75f;

	public int spawnCount = 3;

	public int spawnHealth = 10;

	public float duration = 1f;

	public Transform parentTrans;

	public Vector2 spawnPosition;

	public Seeker currentSeeker;

	public Seeker prevSeeker;

	public string clusterID;

	public List<Seeker> seekerList = new List<Seeker>();

	private ChaosQuickStopwatch checkStopwatch = new ChaosQuickStopwatch(0.25f);

	public bool SeekersActive => seekerList.Count > 0;

	public override string OnEnterAnimStr => parent.PBAoEAnimStr;

	public UseSeekers(string newName, FSM newFSM, Player newEnt)
		: base(newName, newFSM, newEnt)
	{
		isSummonSkill = true;
		disableStartCooldown = true;
		SetAnimTimes(0f, 0.2f, 0.2f, 0.55f, 0.75f);
		clusterID = parent.skillCategory + newName;
	}

	public override bool IsReady()
	{
		if (SeekersActive)
		{
			if (!checkStopwatch.IsRunning)
			{
				checkStopwatch.IsRunning = true;
				seekerList.RemoveNullValues();
			}
			return false;
		}
		return base.IsReady();
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		CreateAllSeekers();
		SoundManager.PlayAudioWithDistance("StandardThrow", spawnPosition);
		CameraController.ShakeCamera(0.125f);
	}

	public virtual void CreateAllSeekers()
	{
		duration = skillData.GetValue<float>("duration");
		prevSeeker = null;
		parentTrans = parent.transform;
		spawnPosition = parentTrans.position;
		spawnCount = skillData.GetValue<int>("spawnCount");
		spawnHealth = skillData.GetValue<int>("baseHealth");
		for (int i = 0; i < spawnCount; i++)
		{
			CreateSeeker(spawnPosition, throwRange * ((spawnCount != 2) ? Globals.GetCirclePositionVector(spawnCount, i) : Globals.GetCirclePositionVector(spawnCount * 2, i * 2 + 1)));
			if (i == 0)
			{
				currentSeeker.SetTransforms(parentTrans, parentTrans, parent.playerSummonsList);
			}
			else if (prevSeeker != null)
			{
				currentSeeker.SetTransforms(parentTrans, prevSeeker.transform);
			}
			prevSeeker = currentSeeker;
		}
	}

	public virtual void CreateSeeker(Vector2 givenPosition, Vector2 givenOffset)
	{
		currentSeeker = ChaosInst<Seeker>(seekerPrefab, givenPosition);
		currentSeeker.gameObject.name = seekerPrefab.name + parent.skillCategory;
		currentSeeker.attack.SetAttackInfo(parent.skillCategory, skillID, currentLevel);
		currentSeeker.isEmpowered = IsEmpowered;
		currentSeeker.ClusterID = clusterID;
		currentSeeker.SetThrowPosition(givenPosition + givenOffset);
		currentSeeker.SetDuration(duration);
		currentSeeker.startingHealth = spawnHealth;
		Seeker seeker = currentSeeker;
		seeker.onDeadEventHandlers = (Seeker.SeekerDeadEventHandler)Delegate.Remove(seeker.onDeadEventHandlers, new Seeker.SeekerDeadEventHandler(OnSeekerDead));
		Seeker seeker2 = currentSeeker;
		seeker2.onDeadEventHandlers = (Seeker.SeekerDeadEventHandler)Delegate.Combine(seeker2.onDeadEventHandlers, new Seeker.SeekerDeadEventHandler(OnSeekerDead));
		seekerList.Add(currentSeeker);
		parent.playerSummonsList.Add(currentSeeker.gameObject);
	}

	public virtual void OnSeekerDead(Seeker givenSeeker)
	{
		if (!(givenSeeker == null))
		{
			givenSeeker.onDeadEventHandlers = (Seeker.SeekerDeadEventHandler)Delegate.Remove(givenSeeker.onDeadEventHandlers, new Seeker.SeekerDeadEventHandler(OnSeekerDead));
			seekerList.Remove(givenSeeker);
			seekerList.RemoveNullValues();
			if (!SeekersActive)
			{
				StartCooldownTimer();
			}
		}
	}
}

