					parent.transform.position = parent.dropPos;
					parent.sprite.transform.position = parent.dropPos + Vector2.up * 4f;
					if (parent.forceDrop)
					{
						ToggleVisuals(givenStatus: true);
						PlaySlamAnim();
						parent.CreateChaosDrop();
						shotStopwatchID = ChaosStopwatch.Begin(0.125f, useInterval: true, 0.125f, 4);
						shotCompleted = false;
					}
					else
					{
						InitCrashDown();
					}
					currentPos = parent.sprite.transform.position + Vector3.up;
					AnimEffect poolItem = PoolManager.GetPoolItem<AnimEffect>("ChaosPortal");
					Vector3 position = currentPos;
					string animName = "Spawn";
					float normalizedTime = 0.3f;
					Vector3? localEulerAngles = Globals.Vector3Angle90CW;
					poolItem.Play(position, animName, normalizedTime, default, 1f, 1f, localEulerAngles);
					ChaosBurst.Spawn(currentPos, 3);
				}
			}
			else if (!shotCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
				{
				case StopwatchState.Ready:
					PlaySlamAnim();
					parent.CreateChaosDrop();
					break;
				case StopwatchState.Done:
					InitCrashDown();
					break;
				}
			}
			else if (!dropCompleted)
			{
				dropLerpValue = ChaosStopwatch.GetTimePercentage(dropStopwatchID);
				parent.sprite.transform.position = Vector2.Lerp(dropStartPos, parent.dropPos, dropLerpValue);
				if (dropLerpValue >= 1f)
				{
					dropCompleted = true;
					parent.CreateChaosPillar();
					fsm.ChangeState("Dead");
				}
			}
		}
		private void InitCrashDown()
		{
			shotCompleted = true;
			dropStartPos = parent.dropPos + Vector2.up * 4.5f;
			parent.sprite.transform.position = dropStartPos;
			dropStopwatchID = ChaosStopwatch.Begin(0.18f);
			dropCompleted = false;
			parent.anim.Play((!(parent.atkVector.y > 0f)) ? "FallDown" : "FallUp", -1, 0f);
			ToggleVisuals(givenStatus: true);
		}
		private void PlaySlamAnim()
		{
			isFaceRight = !isFaceRight;
			parent.anim.Play((!(parent.atkVector.y > 0f)) ? "GroundSlamDown" : "GroundSlamUp", -1, 0.3f);
			parent.transform.localScale = ((!isFaceRight) ? Globals.ScaleVecFlipX : Vector3.one);
		}
		private void ToggleVisuals(bool givenStatus)
		{
			parent.sprite.gameObject.SetActive(givenStatus);
			parent.shadow.gameObject.SetActive(givenStatus);
		}
	}
	private static GameObject prefab;
	public SpriteRenderer shadow;
	public Vector2 atkVector;
	public Vector2 dropPos;
	public bool forceDrop;
	[HideInInspector]
	public int outfitIndex = 24;
	[HideInInspector]
	public bool isUltimate;
	protected bool isClone = true;
	private Quaternion roteQuat;
	private ChaosDrop curDrop;
	private ChaosHado curHado;
	private ChaosPillar curPillar;
	public new static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ChaosDropClone.prefab"));
	protected override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Hado";
		fsm.AddState(new CloneHadoState("Hado", fsm, this));
		fsm.AddState(new CloneDropState("Drop", fsm, this));
		fsm.AddState(new CloneDeadState("Dead", fsm, this));
		fsm.ChangeState((!forceDrop) ? "Hado" : "Drop");
	}
	protected override void Start()
	{
		if (outfitIndex != 24)
		{
			isClone = false;
			sprite.material.SetFloat("_PaletteIndex", outfitIndex);
			sprite.material.SetColor("_OutlineColor", Vector4.zero);
			sprite.material.SetColor("_FlashColor", Color.white);
			sprite.material.SetFloat("_FlashAmount", 0f);
		}
		InitFSM();
		if (!forceDrop)
		{
			roteQuat = Globals.GetRotationQuaternion(atkVector);
			PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(atkTrans.position, "Depart");
		}
	}
	protected override void SetEventHandlers(bool gs)
	{
	}
	private void CreateChaosDrop()
	{
		curDrop = Globals.ChaosInst<ChaosDrop>(ChaosDrop.Prefab, null, (Vector2)transform.position + Random.insideUnitCircle * 0.5f);
		curDrop.attack.SetAttackInfo(skillCat, skillID, 1, isUltimate);
		curDrop.atkSize = 3.5f;
	}
	private void CreateChaosHado()
	{
		curHado = (ChaosHado)Projectile.CreateProjectile(parentPlayer, ChaosHado.Prefab, (Vector2)atkTrans.position + atkVector * 0.5f, roteQuat);
		curHado.attackBox.SetAttackInfo(skillCat, skillID, 2, newIsUltimate: true);
		AttackInfo.SetHurtTargets(curHado.attackBox.atkInfo.targetNames);
		curHado.attackBox.knockbackOverwriteVector = atkVector;
		curHado.moveVector = atkVector;
		SoundManager.PlayWithDistAndSPR("ChaosWarble", transform.position);
		SoundManager.PlayAudioWithDistance("ChaosBall", transform.position, null, 24f, 0.25f);
	}
	private void CreateChaosPillar()
	{
		curPillar = Globals.ChaosInst<ChaosPillar>(ChaosPillar.Prefab, null, dropPos);
		curPillar.attack.SetAttackInfo(skillCat, skillID, 3, isUltimate);
		curPillar.finalAttackLevel = 4;
		curPillar.readyTime = 0.03f;
		curPillar.maxHitCount = 6;
		curPillar.hitInterval = 0.125f;
		curPillar.useCastCircle = false;
		curPillar.useChargeEffect = false;
		curPillar.playSFXOnInterval = true;
	}
}

