	public class SummonDecoyDash : SkillState
	{
		public new static string staticID = "SummonDecoy";
		private GameObject decoyDashPrefab;
		private GameObject currentDecoy;
		private float stealthDuration = 1.5f;
		private int stealthStopwatchID;
		private bool isStealthed;
		public SummonDecoyDash(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			cancelThreshold = 0.5f;
			decoyDashPrefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/DecoyDash.prefab");
		}
		public override void OnEnter()
		{
			BaseOnEnter();
			inputVector = GetInputVector();
			parent.CleanUpPlayerSummonsList();
			currentDecoy = UnityEngine.Object.Instantiate(decoyDashPrefab, parent.transform.position + (Vector3)inputVector, Quaternion.identity);
			currentDecoy.name = decoyDashPrefab.name + parent.skillCategory;
			DecoyDash component = currentDecoy.GetComponent<DecoyDash>();
			component.parentPlayer = parent;
			component.paletteIndex = parent.outfitColorIndex;
			component.dashVector = inputVector;
			component.summonDuration = skillData.GetValue<float>("duration");
			component.health.healthStat.BaseValue = skillData.GetValue<int>("baseHealth");
			component.attack.SetAttackInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
			parent.StartCoroutine(StealthPlayer(parent, stealthDuration));
		}
		public override void Update()
		{
			ExitToSkillOrRunOrIdle();
		}
		private IEnumerator StealthPlayer(Player player, float stealthDur)
		{
			Color spriteColor = Color.white;
			if (parent.playerLight != null)
			{
				parent.playerLight.intensity = 0f;
			}
			if (parent.spriteRenderer != null)
			{
				spriteColor = parent.spriteRenderer.color;
				spriteColor.a = 0f;
				parent.spriteRenderer.color = spriteColor;
			}
			stealthStopwatchID = ChaosStopwatch.Begin(stealthDur);
			if (isStealthed)
			{
				yield break;
			}
			isStealthed = true;
			GameController.allies.Remove(player.gameObject);
			while (!ChaosStopwatch.Check(stealthStopwatchID))
			{
				yield return null;
			}
			isStealthed = false;
			if (player.gameObject != null && !player.fsm.currentStateName.Contains("Dead"))
			{
				GameController.allies.Add(player.gameObject);
			}
			if (parent.playerLight != null && parent.spriteRenderer != null)
			{
				while (!isStealthed && parent.playerLight.intensity <= parent.currentLightIntensity)
				{
					parent.playerLight.intensity += Time.deltaTime * 5f;
					spriteColor.a += Time.deltaTime * 2f;
					parent.spriteRenderer.color = spriteColor;
					yield return null;
				}
			}
			if (!isStealthed)
			{
				if (parent.playerLight != null)
				{
					parent.playerLight.intensity = parent.currentLightIntensity;
				}
				if (parent.spriteRenderer != null)
				{
					spriteColor.a = 1f;
					parent.spriteRenderer.color = spriteColor;
				}
			}
		}
	}
