using UnityEngine;
public class ItemFamiliar : MonoBehaviour
{
	private static GameObject prefab;
	private Animator anim;
	[HideInInspector]
	public string itemID;
	[HideInInspector]
	public Transform parentTransform;
	[HideInInspector]
	public SpriteRenderer spriteRenderer;
	[HideInInspector]
	public float followDistance = 2f;
	[HideInInspector]
	public float idleDistance = 3f;
	[HideInInspector]
	public float shadowWidthScale = 1f;
	private ChaosQuickStopwatch trackingStopwatch;
	private float trackingInterval = 0.1f;
	private float trackingSpeed = 0.075f;
	private float indexWeight = 0.25f;
	private Vector2 currentPosition;
	private Vector2 followPosition;
	private Vector2 trackingPosition;
	private float currentDistance;
	private bool isTracking = true;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/ItemFamiliar.prefab"));
	public virtual void Awake()
	{
		anim = GetComponent<Animator>();
		anim.speed = Random.Range(0.5f, 1f);
		spriteRenderer = base.transform.Find("ItemSprite").GetComponent<SpriteRenderer>();
		Transform transform = base.transform.Find("ShadowScaler/ItemShadow");
		transform.localScale = new Vector3(shadowWidthScale, shadowWidthScale * 0.6f, 1f);
	}
	public virtual void Start()
	{
		if (parentTransform == null)
		{
			DestroyFamiliar();
			return;
		}
		trackingStopwatch = new ChaosQuickStopwatch(trackingInterval);
		currentPosition = parentTransform.position;
		trackingPosition = currentPosition;
	}
	public virtual void FixedUpdate()
	{
		if (!(parentTransform == null))
		{
			currentPosition = transform.position;
			followPosition = parentTransform.position;
			currentDistance = Vector2.Distance(currentPosition, followPosition);
			if (isTracking)
			{
				HandleTracking();
				transform.position = Vector2.Lerp(currentPosition, trackingPosition, trackingSpeed);
				isTracking = currentDistance > followDistance;
			}
			else
			{
				isTracking = currentDistance > idleDistance;
			}
		}
	}
	public virtual void HandleTracking()
	{
		if (!trackingStopwatch.IsRunning)
		{
			trackingStopwatch.IsRunning = true;
			trackingPosition = trackingPosition * (1f - indexWeight) + followPosition * indexWeight;
		}
	}
	public virtual void DeactivateFamiliar()
	{
		anim.Play("Deactivate", -1, 0f);
	}
	public virtual void DestroyFamiliar()
	{
		Object.Destroy(gameObject);
	}
}

