	public class OrbRoamState(string newName, FSM newFSM, OrbFamiliar newEnt) : State<OrbFamiliar>(newName, newFSM, newEnt)
	{
		public string exitStateName = string.Empty;
		private bool roaming;
		private bool targetReached;
		private int roamStopwatchID;
		private float roamDuration = 2f;
		private Vector2 targetLocation;
		public override void OnEnter()
		{
			parent.anim.Play("Idle");
			targetLocation = ((parent.UpdateTargetInfo(parent.CurrentAlertRadius, reqLOS: true) != null) ? parent.closestTargetInfo.position : parent.transform.position);
			targetLocation += Globals.GetCirclePositionVector(8, Random.Range(0, 8)) * Random.Range(0f, parent.attackRadius);
			roamStopwatchID = ChaosStopwatch.Begin(Random.Range(roamDuration * 0.5f, roamDuration));
			roaming = true;
			targetReached = false;
		}
		public override void Update()
		{
			if (!roaming || ChaosStopwatch.Check(roamStopwatchID))
			{
				ExitTransition();
			}
		}
		public override void FixedUpdate()
		{
			if (roaming)
			{
				targetReached = parent.movement.MoveToTarget(targetLocation);
				if (targetReached)
				{
					roaming = false;
				}
			}
		}
		private void ExitTransition()
		{
			if (exitStateName == string.Empty || parent.attackStopwatch.IsRunning || parent.UpdateTargetInfo(parent.attackRadius, reqLOS: true) == null)
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
			else
			{
				fsm.ChangeState(exitStateName);
			}
		}
