		private ChaosQuickStopwatch flashStopwatch = new ChaosQuickStopwatch(0.02f);
		private bool attackStarted;
		private bool attackComplete;
		private Vector3 targetVector;
		private Color lineColor;
		private Color lineColorRed = new Color(0.8f, 0f, 0f, 1f);
		private Color lineColorFlash = new Color(1f, 1f, 1f, 0.75f);
