			{
				parent.auraEmitter.Stop();
			}
			chargeStopwatch.IsRunning = true;
			attackStarted = false;
			attackComplete = false;
			if (parent.attackVector != Vector2.zero)
			{
				targetVector = parent.attackVector;
				parent.attackVector = Vector2.zero;
			}
			else
			{
				targetVector = (parent.closestTargetInfo.position - parent.transform.position).normalized;
			}
