		private bool atkStarted;
		private bool atkCompleted;
		public override void OnEnter()
		{
			parent.movement.EndMovement();
			parent.anim.Play("Speedup", -1, 0f);
			parent.spriteRenderer.material.SetColor("_OutlineColor", Color.cyan);
			PlayAudio();
			targetVector = (parent.closestTargetInfo.position - parent.transform.position).normalized;
			parent.movement.moveVector = targetVector;
			parent.movement.dashVector = targetVector;
			delayStopwatch.IsRunning = true;
			atkStarted = false;
			atkCompleted = false;
		}
		public override void Update()
		{
			if (!delayStopwatch.IsRunning)
			{
				if (!atkStarted)
				{
					atkStarted = true;
				}
				if (atkCompleted)
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
			}
		}
		public override void FixedUpdate()
		{
			if (atkStarted && !atkCompleted)
			{
				PlayAudio();
				if (parent.movement.DashToTarget())
				{
					atkCompleted = true;
					delayStopwatch.IsRunning = true;
					parent.movement.MoveToMoveVector(6f);
					parent.anim.Play("Idle", -1, 0f);
					parent.spriteRenderer.material.SetColor("_OutlineColor", Color.clear);
				}
			}
		}
		public override void OnExit()
		{
			parent.anim.Play("Idle", -1, 0f);
			parent.spriteRenderer.material.SetColor("_OutlineColor", Color.clear);
		}
		private void PlayAudio()
		{
			if (!audioStopwatch.IsRunning)
			{
				audioStopwatch.IsRunning = true;
				SoundManager.PlayAudioWithDistance("StandardSpin", parent.transform.position);
			}
		}
	}
