public class UsePiercingShock : SkillState
{
	public new static string staticID = "UsePiercingShock";
	private PiercingShock currentPS;
	private LightningStream currentLS;
	private bool createdPS;
	private bool createdLS;
	private ParticleEffect[] lightFXArr = new ParticleEffect[3];
	private LightningStrike[] lightStrikesArr = new LightningStrike[5];
	private List<LightningStream> lsList = new List<LightningStream>();
	private LightningStream mainLS;
	private Vector2 startHoldOffset = Vector2.zero;
	private Vector2 endHoldOffset;
	private int streamHitCount = 5;
	private float streamRange = 8f;
	private float velocityMagnitude = 60f;
	private float initKbMultiplier;
	private Vector2 atkPosition;
	private Vector2 prependVec;
	private int targetHitCount;
	private int calcHitCount;
	private float dashDuration = 0.15f;
	private int dashStopwatchID;
	private float dashLerpValue;
	private bool dashCompleted;
	public override string OnEnterAnimStr => parent.ForehandAnimStr;
	public UsePiercingShock(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		isMovementSkill = true;
		isMeleeSkill = true;
		SetAnimTimes(0.1f, 0.2f, 0.1f, 0.6f, 1f);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		if (isUltimate)
		{
			streamHitCount = 8;
			velocityMagnitude = 80f;
			streamRange = 12f;
		}
		else
		{
			streamHitCount = 5;
			if (IsEmpowered)
			{
				velocityMagnitude = 80f;
				streamRange = 10f;
			}
			else
			{
				velocityMagnitude = 60f;
				streamRange = 8f;
			}
		}
		initKbMultiplier = velocityMagnitude;
		endHoldOffset = inputVector * 2f;
		createdPS = false;
		createdLS = false;
		dashCompleted = false;
		targetHitCount = 0;
		lsList.Clear();
	}
	public override void ExecuteSkill()
	{
		if (!createdPS)
		{
			createdPS = true;
			CreatePiercingShock();
			parent.ToggleEnemyFloorCollisions(status: false);
			parent.rigidbody2D.velocity = inputVector * velocityMagnitude * parent.movement.dashDurationStat.CurrentValue * 8f;
			dashStopwatchID = ChaosStopwatch.Begin(dashDuration);
		}
		if (dashCompleted)
		{
			if (currentPS != null && !currentPS.destroyQueued)
			{
				currentPS.Reset();
				currentPS = null;
				StopLightningEffects();
			}
			if (!createdLS)
			{
				createdLS = true;
				HandleLightningStreams();
			}
			if (mainLS == null)
			{
				base.ExecuteSkill();
				StopLightningEffects();
				StopLightingStrikes();
			}
			CancelToDash();
			if (parent.anim.AnimPlayed(cancelThreshold))
			{
				parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, 0.3f);
			}
		}
	}
	public override void FixedUpdate()
	{
		if (!createdPS || dashCompleted)
		{
			return;
		}
		dashLerpValue = ChaosStopwatch.GetTimePercentage(dashStopwatchID);
		if (currentPS != null)
		{
			currentPS.transform.position = parent.attackOriginTrans.position + Vector3.Lerp(startHoldOffset, endHoldOffset, dashLerpValue * dashLerpValue);
			currentPS.attack.atkInfo.knockbackMultiplier = initKbMultiplier * parent.rigidbody2D.velocity.magnitude / velocityMagnitude;
		}
		if (dashLerpValue >= 1f)
		{
			dashCompleted = true;
			parent.movement.EndMovement();
			if (targetHitCount == 0)
			{
				parent.movement.moveVector = inputVector;
				parent.movement.MoveToMoveVector();
			}
			else
			{
				parent.rigidbody2D.AddForce(-inputVector * 8f, ForceMode2D.Impulse);
			}
		}
	}

