	private void StartDash(Vector3 givenVec, bool isReverse = true)
	{
		FaceTarget(transform.position + ((!isReverse) ? givenVec : (-givenVec)), 2);
		SetXScale();
		anim.Play((!isReverse) ? "JumpAttackFront" : "Dash", -1, 0f);
		movement.moveVector = givenVec;
		movement.dashVector = givenVec;
		dashCompleted = false;
		delayStopwatchID = ChaosStopwatch.Begin(0.15f);
	}
	private bool FindTarget()
	{
		targetList = Entity.GetAllTargetsInRange(GameController.enemies, transform.position, 12f, playerTagOnly: false, playerSummonsList, parentEnt.gameObject, requireLOS: true, ChaosCollisions.layerUpperWallAndObst);
		if (targetList != null && targetList.Count > 0)
		{
			targetInfo = Entity.GetTargetInfoFromObject(targetList[Random.Range(0, targetList.Count)]);
			targetList.Clear();
			if (targetInfo != null && arrowSpawn != null)
			{
				return true;
			}
		}
		return false;
	}
	private void AimTowardsTarget(bool useTimer = true)
	{
		if (currentProj != null)
		{
			currentProj.transform.position = arrowSpawn.position;
		}
		if ((!useTimer || !aimStopwatch.IsRunning) && targetInfo != null && !(targetInfo.transform == null) && !(targetInfo.hurtBoxTransform == null))
		{
			aimStopwatch.IsRunning = useTimer;
			FaceTarget(targetInfo.transform.position, 2);
			SetXScale();
			aimVector = (targetInfo.hurtBoxTransform.position - arrowSpawn.position).normalized;
			roteVector = Globals.GetRotationVector(aimVector);
			armVector = roteVector;
			if (!isFacingRight)
			{
				armVector.z *= -1f;
			}
			armVector.z += 90f;
			if (bowArm != null)
			{
				bowArm.localEulerAngles = armVector;
			}
			if (!(currentProj == null))
			{
				currentProj.RefreshFlightTime();
				currentProj.transform.localEulerAngles = roteVector;
			}
		}
	}
	private void CreateSpreadShot()
	{
		currentPos = (Vector2)arrowSpawn.position - aimVector * 0.5f;
		for (int i = 0; i < 5; i++)
		{
			CreateProjectile(currentPos, Globals.GetRotatedCircleVector(24, i - 2, aimVector), skillLv, release: true);
		}
	}
	private void CreateProjectile(Vector2 givenPos, Vector2 givenVec, int givenLv, bool release = false)
	{
		currentProj = Projectile.CreateProjectile(parentEnt, ProjPrefab, givenPos, Globals.GetRotationQuaternion(givenVec));
		currentProj.attackBox.SetAttackInfo(skillCategory, skillID, givenLv);
		currentProj.Show();
		currentProj.attackBox.gameObject.SetActive(value: false);
		currentProj.wallCollider.gameObject.SetActive(value: false);
		if (release)
		{
			ReleaseProjectile(currentProj, givenVec, givenDisable: false);
			currentProj = null;
		}
	}
	private void ReleaseProjectile(Projectile givenProj, Vector2 givenVec, bool givenDisable = true)
	{
		if (!(givenProj == null))
		{
			givenProj.transform.localEulerAngles = Globals.GetRotationVector(givenVec);
			givenProj.moveVector = givenVec;
			givenProj.attackBox.knockbackOverwriteVector = givenVec;
			givenProj.attackBox.gameObject.SetActive(value: true);
			givenProj.wallCollider.gameObject.SetActive(value: true);
			SoundManager.PlayAudioWithDistance("ArcherAttackRelease", transform.position);
			SoundManager.PlayAudioWithDistance("ArcherArrow", transform.position);
			givenProj.moveSpeed = 40f;
			givenProj.flyTime = 0.3f;
			givenProj.RefreshFlightTime();
			givenProj.goThroughWalls = false;
			givenProj.disableOnHit = givenDisable;
			givenProj.projectileSpriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.1f));
		}
	}
	private void EndAttack()
	{
		anim.Play("GroundSlam", -1, 0.3f);
		resetStopwatchID = ChaosStopwatch.Begin(0.25f);
		resetQueued = true;
		currentPos = transform.position + Vector3.up;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(3, currentPos);
		SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", currentPos);
	}
	private void Reset()
	{
		currentPos = transform.position + Vector3.up;
		PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect").Emit(3, currentPos, ParticleEffectOverrides.StartLifeTime0p25);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Depart");
		string audioID = "EnemyDead";
		Vector2? soundOrigin = currentPos;
		float overridePitch = Random.Range(1.1f, 1.2f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		Object.Destroy(gameObject);
	}
}

public class UseBaseMinion : SkillState
{
	public GameObject minionPrefab;
	public List<BasicMinion> minionList = new List<BasicMinion>();
	public BasicMinion currentMinion;
	public SyncedNumVarStat maxSummonStat = new SyncedNumVarStat(3f);
	public int summonCount = 1;
	public int currentCount;
	public Vector2 spawnLocation;
	public Vector2 spawnOffset;
	public float summonDuration;
	public int summonHealth;
	public override string OnEnterAnimStr => parent.PBAoEAnimStr;
	public UseBaseMinion(string newName, FSM newFSM, Player newPlayer)
		: base(newName, newFSM, newPlayer)
	{
		isSummonSkill = true;
		SetAnimTimes(0.1f, 0.2f, 0.3f, 0.8f, 0.9f);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		parent.odPauseStopwatch.IsRunning = true;
	}
	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		summonCount = skillData.GetValue<int>(StatData.spawnStr);
		summonDuration = skillData.GetValue<float>(StatData.durStr);
		summonHealth = skillData.GetValue<int>(StatData.healthStr);
		spawnLocation = parent.transform.position;
		SummonAllMinions();
		CameraController.ShakeCamera(0.25f);
	}
	public virtual void LimitToMaxMinions()
	{
		if ((float)minionList.Count > maxSummonStat.CurrentValue && minionList[0] != null)
		{
			minionList[0].DestroyMinion();
			minionList.RemoveAt(0);
		}
	}
	public virtual void SummonAllMinions()
	{
		minionList.RemoveNullValues();
		parent.CleanUpPlayerSummonsList();
		for (currentCount = 0; currentCount < summonCount; currentCount++)
		{
			SummonMinion();
			LimitToMaxMinions();
		}
	}
	public virtual BasicMinion SummonMinion()
	{
		currentMinion = ChaosInst<BasicMinion>(minionPrefab, GetSpawnLocation());
		currentMinion.gameObject.name = minionPrefab.name + parent.skillCategory;
		currentMinion.parentTrans = parent.transform;
		currentMinion.parentSummonList = parent.playerSummonsList;
		currentMinion.SetSkillInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
		currentMinion.summonDuration = summonDuration;
		currentMinion.startingHealth = summonHealth;
		currentMinion.isEmpowered = IsEmpowered;
		if (Inventory.EitherPlayerHasItem(FlatDamage.staticID) && FlatDamage.damageMod != null)
		{
			currentMinion.health.damageTakenStat.Modify(FlatDamage.damageMod, addMod: true);
		}
		minionList.Add(currentMinion);
		parent.playerSummonsList.Add(currentMinion.gameObject);
		return currentMinion;
	}
	public virtual Vector2 GetSpawnLocation()
	{
		spawnOffset = Entity.GetAvailableNearbyLocation(spawnLocation + Globals.GetRotatedCircleVector(summonCount, currentCount, inputVector), excludeOrigin: false, randomize: false);
		return (!(spawnOffset == Vector2.zero)) ? spawnOffset : spawnLocation;
	}
}
