				attackBoxSize.y = Mathf.Lerp(0.1f, 3f, sizeLerpValue);
				attackBox.size = attackBoxSize;
				attackBoxOffset.y = Mathf.Lerp(0f, 1.5f, sizeLerpValue);
				attackBox.offset = attackBoxOffset;
