using System.Collections.Generic;
using UnityEngine;
public class PoisonCloud : MonoBehaviour
{
	public float radius = 1f;
	public bool spawnOnStart;
	public bool destroyOnStop = true;
	private bool markedForDestroy;
	private int cloudCount = 1;
	private GameObject[] poisonClouds;
	private ParticleSystem[] particleSystems;
	private ParticleSystem.MainModule partSysMainMod;
	private Light[] lights;
	public bool useAltColor;
	private Color altColor = new Color32(125, 75, 175, 153);
	private float centerCloudThresholdRadius = 2.5f;
	private static GameObject _unitPrefab;
	private static GameObject _prefab;
	public static GameObject UnitPrefab
	{
		get
		{
			if (_unitPrefab == null)
			{
				_unitPrefab = ChaosBundle.Get("Assets/Prefabs/Effects/PoisonCloudUnit.prefab");
			}
			return _unitPrefab;
		}
	}
	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PoisonCloud.prefab");
			}
			return _prefab;
		}
	}
	private void Start()
	{
		if (spawnOnStart)
		{
			InitializeRadius();
		}
	}
	public static PoisonCloud Spawn(Vector3 position, float radius = 1f, bool spawnOnStart = true, bool destroyOnStop = true)
	{
		PoisonCloud component = Object.Instantiate(Prefab, position, Quaternion.identity).GetComponent<PoisonCloud>();
		component.radius = radius;
		component.spawnOnStart = spawnOnStart;
		component.destroyOnStop = destroyOnStop;
		return component;
	}
	public void Play()
	{
		InitializeRadius();
	}
	public void Stop()
	{
		for (int i = 0; i < particleSystems.Length; i++)
		{
			ParticleSystem particleSystem = particleSystems[i];
			ParticleSystem.EmissionModule emission = particleSystem.emission;
			emission.enabled = false;
			particleSystem.Stop();
		}
		for (int j = 0; j < lights.Length; j++)
		{
			lights[j].enabled = false;
		}
		if (destroyOnStop && !markedForDestroy)
		{
			markedForDestroy = true;
			Object.Destroy(gameObject, 2.5f);
		}
	}
	public void InitializeRadius()
	{
		List<GameObject> list = new List<GameObject>();
		List<ParticleSystem> list2 = new List<ParticleSystem>();
		List<Light> list3 = new List<Light>();
		if (radius <= 1f)
		{
			cloudCount = 1;
		}
		else if (radius <= 2.5f)
		{
			cloudCount = 4;
		}
		else
		{
			cloudCount = 8;
		}
		for (int i = 0; i < cloudCount; i++)
		{
			SpawnPoisonCloud(Globals.GetCirclePositionVector(cloudCount, i) * radius * 0.6f, list, list2, list3);
		}
		if (radius > centerCloudThresholdRadius)
		{
			SpawnPoisonCloud(Vector3.zero, list, list2, list3);
		}
		poisonClouds = list.ToArray();
		particleSystems = list2.ToArray();
		lights = list3.ToArray();
		cloudCount = poisonClouds.Length;
		if (useAltColor)
		{
			for (int num = particleSystems.Length - 1; num >= 0; num--)
			{
				if (particleSystems[num].name.Contains("CenterEmitter"))
				{
					partSysMainMod = particleSystems[num].main;
					partSysMainMod.startColor = altColor;
				}
			}
		}
		if (cloudCount <= 1)
		{
			return;
		}
		for (int j = 0; j < lights.Length; j++)
		{
			if (j < lights.Length - 1)
			{
				lights[j].enabled = false;
				continue;
			}
			lights[j].range = radius * 1.5f;
			lights[j].intensity *= 0.66f;
		}
	}
	private GameObject SpawnPoisonCloud(Vector3 position, List<GameObject> cloudList = null, List<ParticleSystem> pSysList = null, List<Light> lightList = null)
	{
		GameObject gameObject = Object.Instantiate(UnitPrefab, transform.position + position, Quaternion.identity);
		gameObject.transform.SetParent(transform);
		cloudList?.Add(gameObject);
		pSysList?.AddRange(gameObject.GetComponentsInChildren<ParticleSystem>());
		lightList?.AddRange(gameObject.GetComponentsInChildren<Light>());
		return gameObject;
	}
}

