	private void SetRadius(float radius = 1f)
	{
		localScale = radius * 2f;
		transform.localScale = new Vector3(localScale, localScale, 1f);
		for (int i = 0; i < emissionMods.Length; i++)
		{
			emissionMods[i].rateOverTime = new ParticleSystem.MinMaxCurve(startEmissionRates[i] * localScale, startEmissionRates[i] * localScale);
		}
	}
	private void Awake()
	{
		particleSystems = GetComponentsInChildren<ParticleSystem>();
		emissionMods = new ParticleSystem.EmissionModule[particleSystems.Length];
		startEmissionRates = new float[particleSystems.Length];
		for (int i = 0; i < particleSystems.Length; i++)
		{
			ref ParticleSystem.EmissionModule reference = ref emissionMods[i];
			reference = particleSystems[i].emission;
			startEmissionRates[i] = emissionMods[i].rateOverTime.constantMax;
		}
		fgEmitterMain = fgEmitter.main;
		auraEmitterMain = auraEmitter.main;
		baseEmitterMain = baseEmitter.main;
		baseParticles = new ParticleSystem.Particle[baseEmitter.maxParticles];
		fgParticles = new ParticleSystem.Particle[fgEmitter.maxParticles];
	}
