		shadowSprite.enabled = true;
		effectCircle.enabled = true;
		for (int i = 0; i < particleSystems.Length; i++)
		{
			emissionMods[i].enabled = true;
			particleSystems[i].Play();
		}
		baseEmitter.Emit((int)(4f * localScale));
		disableQueued = false;
		disableStopwatch.IsRunning = false;
	}
	public void Stop()
	{
		if (gameObject != null)
		{
			shadowSprite.enabled = false;
			effectCircle.enabled = false;
			int particles = baseEmitter.GetParticles(baseParticles);
			for (int i = 0; i < particles; i++)
			{
				baseParticles[i].remainingLifetime = 0.66f;
			}
			baseEmitter.SetParticles(baseParticles, particles);
			particles = fgEmitter.GetParticles(fgParticles);
			for (int j = 0; j < particles; j++)
			{
				fgParticles[j].remainingLifetime = 0.66f;
			}
			fgEmitter.SetParticles(fgParticles, particles);
			auraEmitter.Clear();
			for (int k = 0; k < particleSystems.Length; k++)
			{
				emissionMods[k].enabled = false;
				particleSystems[k].Stop();
			}
			if (destroyOnDisable)
			{
				Object.Destroy(gameObject, destroyDelay);
			}
			else if (gameObject.activeSelf)
			{
				StartCoroutine(DelayedDisable());
			}
		}
	}
	private IEnumerator DelayedDisable()
	{
		if (disableStopwatch.IsRunning)
		{
			disableStopwatch.IsRunning = true;
			yield break;
		}
		disableQueued = true;
		disableStopwatch.IsRunning = true;
		while (disableStopwatch.IsRunning)
		{
			yield return null;
		}
		if (disableQueued)
		{
			disableQueued = false;
			gameObject.SetActive(value: false);
		}
	}
