using UnityEngine;
public class ChaosBasic : Projectile
{
	private static GameObject prefab;
	public Light chaosLight;
	public CircleCollider2D attackCollider;
	public bool resetOnShrink;
	private bool moveStopped;
	private float moveLerpValue;
	private float baseMoveSpeed;
	private ChaosQuickStopwatch moveStopwatch = new ChaosQuickStopwatch(0.1f);
	private bool shrinkCompleted;
	private float shrinkLerpValue;
	private ChaosQuickStopwatch shrinkStopwatch = new ChaosQuickStopwatch(0.35f);
	private float shootSpeed = 40f;
	private float shootTime = 0.35f;
	private float baseAtkRadius = 1f;
	private float shrinkAtkRadius = 0.4f;
	public static ParticleSystemOverride darkChaosOverride = new ParticleSystemOverride
	{
		startColor = new Color32(85, 40, 180, byte.MaxValue),
		radius = 0.25f,
		startSpeed = 0.1f
	};
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ChaosBasic.prefab"));
	public override void Start()
	{
		base.Start();
		baseAtkRadius = attackCollider.radius;
		baseMoveSpeed = moveSpeed;
		moveStopwatch.IsRunning = true;
		string audioID = "ChaosBeamStart";
		Vector2? soundOrigin = transform.position;
		float overridePitch = Random.Range(1.1f, 1.2f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.2f, overridePitch);
		PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(1, transform.position + (Vector3)moveVector, darkChaosOverride);
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!moveStopped)
		{
			moveLerpValue = moveStopwatch.TimePercentage;
			moveSpeed = Mathf.Lerp(baseMoveSpeed, 0f, moveLerpValue);
			moveStopped = moveLerpValue >= 1f;
			if (moveStopped)
			{
				Shrink();
			}
		}
		else
		{
			if (shrinkCompleted)
			{
				return;
			}
			shrinkLerpValue = shrinkStopwatch.TimePercentage;
			attackCollider.radius = Mathf.Lerp(baseAtkRadius, shrinkAtkRadius, shrinkLerpValue);
			chaosLight.intensity = Mathf.Lerp(5f, 1f, shrinkLerpValue);
			shrinkCompleted = shrinkLerpValue >= 1f;
			if (shrinkCompleted)
			{
				if (resetOnShrink || !Globals.CheckCircle(transform.position, shrinkAtkRadius, ChaosCollisions.layerUpperWall))
				{
					ResetProjectile();
					return;
				}
				attackBox.ChangeAttackInfoLevel(2);
				attackCollider.enabled = true;
				goThroughWalls = false;
				moveSpeed = shootSpeed;
				flyTime = shootTime;
				RefreshFlightTime();
				ChaosBurst.Spawn(transform.position, 1);
				PoolManager.GetPoolItem<DashAirBurst>().Burst(transform.position + (Vector3)moveVector * 0.25f, moveVector);
				SoundManager.PlayWithDistAndSPR("ChaosBall", transform.position);
			}
		}
	}
	public override void ResetProjectile()
	{
		base.ResetProjectile();
		ChaosBurst.Spawn(transform.position, 2);
		string audioID = "EnemyDead";
		Vector2? soundOrigin = transform.position;
		float overridePitch = Random.Range(1.1f, 1.2f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
	}
	private void Shrink()
	{
		shrinkCompleted = false;
		shrinkStopwatch.IsRunning = true;
		if (!resetOnShrink)
		{
			attackCollider.enabled = false;
		}
		ChaosBurst.Spawn(transform.position, 1);
	}
}
